def move_duplicates_to_their_tables(apps, schema_editor):
    """Keep what the removed fields did: prizes, place achievements and admission rules move to their
    tables, and a free tournament keeps no entry fee."""
    Tournament = apps.get_model("tournaments", "Tournament")
    TournamentPrize = apps.get_model("tournaments", "TournamentPrize")
    TournamentAchievement = apps.get_model("tournaments", "TournamentAchievement")
    TournamentEligibilityRule = apps.get_model("tournaments", "TournamentEligibilityRule")

    Tournament.objects.filter(entry_type="free").exclude(entry_fee_coins=0).update(entry_fee_coins=0)

    for tournament in Tournament.objects.all().iterator():
        prizes = {prize.place: prize for prize in TournamentPrize.objects.filter(tournament=tournament)}
        legacy_money = {1: tournament.prize_first, 2: tournament.prize_second, 3: tournament.prize_third}
        for place, amount in legacy_money.items():
            if not amount or amount <= 0:
                continue
            prize = prizes.get(place)
            if prize is None:
                prizes[place] = TournamentPrize.objects.create(tournament=tournament, place=place, money_amount=amount)
            elif not prize.is_active:
                # An inactive row used to fall back to the money field; it now carries that money itself.
                prize.money_amount, prize.coins_amount, prize.vip_days = amount, 0, 0
                prize.achievement = None
                prize.is_active = True
                prize.save(update_fields=["money_amount", "coins_amount", "vip_days", "achievement", "is_active"])

        for place, kind in PLACE_KINDS.items():
            achievement = (
                TournamentAchievement.objects.filter(tournament=tournament, kind=kind).order_by("sort_order", "id").first()
            )
            if achievement is None:
                continue
            prize = prizes.get(place)
            if prize is None:
                prizes[place] = TournamentPrize.objects.create(tournament=tournament, place=place, achievement=achievement)
            elif prize.is_active and prize.achievement_id is None:
                prize.achievement = achievement
                prize.save(update_fields=["achievement"])

        legacy_rules = (
            ("predictions_count", tournament.min_user_predictions),
            ("winning_predictions_count", tournament.min_user_wins),
        )
        for rule_type, value in legacy_rules:
            if value:
                TournamentEligibilityRule.objects.create(
                    tournament=tournament,
                    rule_type=rule_type,
                    operator="gte",
                    value=value,
                    sport_id=tournament.eligibility_sport_id,
                )


